import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import Database from 'better-sqlite3';
import { drizzle } from 'drizzle-orm/better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import * as schema from './schema.ts';

/** SQL migrations generated by drizzle-kit from `schema.ts`, applied in order on startup. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../../drizzle', import.meta.url));

/**
 * Opens the SQLite database with the settings from ADR 0002. `path` may be `:memory:`.
 * The parent directory is created if it doesn't exist yet.
 */
export function openDatabase(path: string) {
  if (path !== ':memory:') {
    mkdirSync(dirname(path), { recursive: true });
  }
  const sqlite = new Database(path);
  // busy_timeout first, so the switch to WAL waits instead of failing if the file is locked.
  sqlite.pragma('busy_timeout = 5000');
  sqlite.pragma('journal_mode = WAL');
  sqlite.pragma('foreign_keys = ON');
  sqlite.pragma('synchronous = NORMAL');
  return drizzle({ client: sqlite, schema });
}

export type Db = ReturnType<typeof openDatabase>;

/** The handle inside `db.transaction((tx) => …)`. Transactions are synchronous with better-sqlite3. */
export type Tx = Parameters<Parameters<Db['transaction']>[0]>[0];

/** Applies every migration that hasn't run yet. Already-applied migrations are skipped. */
export function migrateDatabase(db: Db): void {
  migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
}
